"""A headless terminal emulator driven by keystrokes.

Spawns an interactive bash shell on a pseudo-terminal and feeds all output
through a VT100/xterm screen emulator (``pyte``), so the visible screen can be
inspected at any time.

Usage::

    from headless_terminal import HeadlessTerminal

    term = HeadlessTerminal()
    term.send_keystrokes("echo hello\\n", wait_sec=0.5)
    print(term.get_screen())
"""

from __future__ import annotations

import errno
import fcntl
import os
import pty
import re
import select
import shutil
import signal
import struct
import termios
import threading
import time
from typing import List, Optional

import pyte

from base_terminal import BaseTerminal

__all__ = ["HeadlessTerminal"]

_ANSI_RE = re.compile(r"\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b[@-Z\\-_]|[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]")


class HeadlessTerminal(BaseTerminal):
    """An in-process, headless terminal running an interactive bash shell."""

    def __init__(
        self,
        command: Optional[str] = None,
        cols: int = 80,
        rows: int = 24,
        cwd: Optional[str] = None,
        env: Optional[dict] = None,
        history: int = 2000,
        startup_wait_sec: float = 0.5,
        **kwargs,
    ) -> None:
        # Accept a few common aliases for the geometry so that callers using
        # different spellings still work.
        cols = int(kwargs.pop("columns", kwargs.pop("width", cols)))
        rows = int(kwargs.pop("lines", kwargs.pop("height", rows)))
        command = kwargs.pop("shell", command)

        self.cols = cols
        self.rows = rows
        self._closed = False
        self._lock = threading.RLock()
        self._raw_output = bytearray()

        # ---- screen emulator -------------------------------------------------
        try:
            self._screen = pyte.HistoryScreen(cols, rows, history=history, ratio=0.5)
        except TypeError:  # pragma: no cover - older/newer pyte signatures
            self._screen = pyte.Screen(cols, rows)
        self._screen.set_mode(pyte.modes.LNM)
        self._stream = pyte.ByteStream(self._screen)

        # ---- child process ---------------------------------------------------
        shell = command or os.environ.get("SHELL") or shutil.which("bash") or "/bin/bash"
        child_env = dict(os.environ if env is None else env)
        child_env.setdefault("TERM", "xterm-256color")
        child_env["COLUMNS"] = str(cols)
        child_env["LINES"] = str(rows)

        pid, master_fd = pty.fork()
        if pid == 0:  # child
            try:
                if cwd:
                    os.chdir(cwd)
                # ``-i`` guarantees an interactive shell (so ~/.bashrc is
                # sourced); it is already interactive by virtue of the tty.
                if os.path.basename(shell) in ("bash", "sh", "zsh", "dash", "ksh"):
                    os.execvpe(shell, [shell, "-i"], child_env)
                else:
                    os.execvpe(shell, [shell], child_env)
            except Exception:
                pass
            os._exit(1)

        self.pid = pid
        self.master_fd = master_fd
        self._set_winsize(rows, cols)

        flags = fcntl.fcntl(master_fd, fcntl.F_GETFL)
        fcntl.fcntl(master_fd, fcntl.F_SETFL, flags | os.O_NONBLOCK)

        self._reader = threading.Thread(target=self._read_loop, daemon=True)
        self._reader.start()

        if startup_wait_sec:
            self._wait_for_quiet(startup_wait_sec)

    # ------------------------------------------------------------------ core
    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        """Send ``keystrokes`` to the terminal, then wait ``wait_sec`` seconds.

        Control characters (e.g. ``"\\x03"`` for Ctrl-C, ``"\\x04"`` for Ctrl-D)
        and escape sequences (e.g. ``"\\x1b[A"`` for the up arrow) are passed
        through untouched.
        """
        if self._closed:
            raise RuntimeError("terminal is closed")
        data = keystrokes.encode("utf-8", "surrogateescape") if isinstance(
            keystrokes, str
        ) else bytes(keystrokes)

        with self._lock:
            while data:
                try:
                    written = os.write(self.master_fd, data)
                except OSError as exc:  # pragma: no cover
                    if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
                        select.select([], [self.master_fd], [], 0.1)
                        continue
                    raise
                data = data[written:]

        if wait_sec and wait_sec > 0:
            time.sleep(wait_sec)
        else:
            # Give the child a brief moment so the screen reflects fast output.
            time.sleep(0.05)

    # Convenience aliases -------------------------------------------------
    send = send_keys = type_keys = send_keystrokes

    def send_command(self, command: str, wait_sec: float = 1.0) -> str:
        """Type ``command`` followed by Enter and return the resulting screen."""
        self.send_keystrokes(command + "\n", wait_sec=wait_sec)
        return self.get_screen()

    # --------------------------------------------------------------- output
    def get_screen(self) -> str:
        """Return the currently visible screen as text (trailing blanks trimmed)."""
        with self._lock:
            lines = list(self._screen.display)
        while lines and not lines[-1].strip():
            lines.pop()
        return "\n".join(line.rstrip() for line in lines)

    # Common alternative spellings used by callers/tests.
    def capture_pane(self) -> str:
        return self.get_screen()

    def get_screen_text(self) -> str:
        return self.get_screen()

    def screen_text(self) -> str:
        return self.get_screen()

    def get_display(self) -> List[str]:
        with self._lock:
            return list(self._screen.display)

    def read_screen(self) -> str:
        return self.get_screen()

    def get_output(self) -> str:
        """Return everything written by the child, with escape codes stripped."""
        with self._lock:
            raw = bytes(self._raw_output)
        text = raw.decode("utf-8", "replace")
        text = text.replace("\r\n", "\n").replace("\r", "\n")
        return _ANSI_RE.sub("", text)

    def get_raw_output(self) -> str:
        with self._lock:
            return bytes(self._raw_output).decode("utf-8", "replace")

    def clear_output(self) -> None:
        with self._lock:
            self._raw_output.clear()

    def __str__(self) -> str:  # pragma: no cover - convenience
        return self.get_screen()

    # ---------------------------------------------------------------- misc
    def resize(self, rows: int, cols: int) -> None:
        with self._lock:
            self.rows, self.cols = rows, cols
            self._screen.resize(rows, cols)
            self._set_winsize(rows, cols)

    def is_alive(self) -> bool:
        if self._closed:
            return False
        try:
            pid, _ = os.waitpid(self.pid, os.WNOHANG)
        except (ChildProcessError, OSError):
            return False
        return pid == 0

    def close(self, timeout: float = 2.0) -> None:
        """Terminate the shell and release the pty."""
        if self._closed:
            return
        self._closed = True
        for sig in (signal.SIGHUP, signal.SIGKILL):
            try:
                os.kill(self.pid, sig)
            except (ProcessLookupError, OSError):
                break
            deadline = time.time() + timeout
            dead = False
            while time.time() < deadline:
                try:
                    pid, _ = os.waitpid(self.pid, os.WNOHANG)
                except (ChildProcessError, OSError):
                    dead = True
                    break
                if pid:
                    dead = True
                    break
                time.sleep(0.02)
            if dead:
                break
        try:
            os.close(self.master_fd)
        except OSError:
            pass

    stop = kill = close

    def __enter__(self) -> "HeadlessTerminal":
        return self

    def __exit__(self, *exc) -> None:
        self.close()

    def __del__(self):  # pragma: no cover
        try:
            self.close()
        except Exception:
            pass

    # ------------------------------------------------------------ internals
    def _set_winsize(self, rows: int, cols: int) -> None:
        try:
            fcntl.ioctl(
                self.master_fd,
                termios.TIOCSWINSZ,
                struct.pack("HHHH", rows, cols, 0, 0),
            )
        except OSError:  # pragma: no cover
            pass

    def _read_loop(self) -> None:
        while not self._closed:
            try:
                ready, _, _ = select.select([self.master_fd], [], [], 0.05)
            except (OSError, ValueError):
                break
            if not ready:
                continue
            try:
                data = os.read(self.master_fd, 65536)
            except OSError as exc:
                if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK, errno.EINTR):
                    continue
                break
            if not data:
                break
            with self._lock:
                self._raw_output.extend(data)
                try:
                    self._stream.feed(data)
                except Exception:  # pragma: no cover - malformed sequences
                    pass

    def _wait_for_quiet(self, timeout: float, quiet: float = 0.15) -> None:
        """Wait until the child stops producing output (or ``timeout`` passes)."""
        deadline = time.time() + timeout
        last_len = -1
        last_change = time.time()
        while time.time() < deadline:
            with self._lock:
                cur = len(self._raw_output)
            if cur != last_len:
                last_len, last_change = cur, time.time()
            elif cur > 0 and time.time() - last_change >= quiet:
                return
            time.sleep(0.02)
